function calcularDV(nit) {
  const nitStr = String(nit).replace(/[^0-9]/g, '');
  const pesos = [71, 67, 59, 53, 47, 43, 41, 37, 29, 23, 19, 17, 13, 7, 3];
  const offset = pesos.length - nitStr.length;
  let suma = 0;
  for (let i = 0; i < nitStr.length; i++) {
    suma += parseInt(nitStr[i]) * pesos[offset + i];
  }
  const resto = suma % 11;
  return (resto === 0 || resto === 1) ? resto : 11 - resto;
}

return items.map(item => {
  const expense = item.json;

  const nitField = (expense.ExtraFields || [])
    .find(f => f.Name === "NIT Proveedor");

  let nit = null;

  if (nitField?.Value) {
    nit = nitField.Value.includes('-')
      ? nitField.Value.split('-')[0].trim()
      : nitField.Value.trim();
  }

  const dv = nit ? calcularDV(nit) : null;

  return {
    json: {
      ...expense,
      nitProveedor: 'P' + nit,
      nitLimpio: nit,
      dvCalculado: dv,
      nitConDV: nit ? (nit + '-' + dv) : null
    }
  };
});

const unique = new Map();

for (const item of items) {
  const expense = item.json;

  const nitField = (expense.ExtraFields || [])
    .find(f => f.Name === "NIT Proveedor");

  let nit = null;

  if (nitField?.Value) {
    nit = nitField.Value.includes('-')
      ? nitField.Value.split('-')[0].trim()
      : nitField.Value.trim();
  }

  if (!nit) continue;

  if (!unique.has(nit)) {
    unique.set(nit, {
      json: {
        nitProveedor: nit,
        gastos: []
      }
    });
  }

  unique.get(nit).json.gastos.push(expense);
}

return Array.from(unique.values());

