={{ JSON.stringify((() => {
  const allTaxes = $json.MultipleTaxes?.taxes ?? [];
  const net = parseFloat($json.Net ?? $json.OriginalAmount ?? 0);
  const oficina  = $json.ExtraFields?.find(f => f.Name === 'Oficina')?.Code;
  const area     = $json.ExtraFields?.find(f => f.Name === 'Area')?.Code;
  const itemCode = $json.CategoryCode;
  const lineBase = { Quantity: 1, CostingCode: 'CO', CostingCode4: parseInt(oficina), CostingCode5: area };
  const docDate = ($json.IssueDate).split('T')[0];

  // Aislar impuesto al consumo (IMPC*) → va a DocumentAdditionalExpenses, no a línea de impuesto
  const CONSUMO_EXP_CODE = 8;
  const consumoLines = allTaxes.filter(t => t.code && t.code.startsWith('IMPC'));

  const taxLines   = allTaxes.filter(t => t.code && t.type !== 2 && !t.code.startsWith('IMPC'));
  const retenLines = allTaxes.filter(t => t.code && (t.type === 2 || parseFloat(t.retentionAmount ?? 0) > 0));

  const retenMap = {
    'RETASUM53': { wtCode: 'RIN1', sapItem: 'RETASUM53' },
    'RETICAASUM53':  { wtCode: 'RS4N',  sapItem: 'RETICAASUM53' },
  };

  const taxDocLines = taxLines.length > 0
    ? taxLines.map(t => ({ ...lineBase, ItemCode: itemCode, Price: parseFloat(t.baseAmount), TaxCode: t.code }))
    : (() => {
        const singleCode = $json.Taxes?.code;
        const defaultCode = consumoLines.length > 0 ? 'IVAEXC' : (singleCode || undefined);
        return [{ ...lineBase, ItemCode: itemCode, Price: net, ...(defaultCode ? { TaxCode: defaultCode } : {}) }];
      })();

  const retenDocLines = retenLines
  .map(t => {
    const wtAmount  = parseFloat(t.retentionAmount ?? t.retention ?? 0);
    const firstWord = (t.retentionName ?? '').trim().split(/\s+/)[0].toUpperCase();
    const sapItem   = firstWord === 'RETEICA' ? 'RETICAASUM53' : 'RETASUM53';
    return { ...lineBase, ItemCode: sapItem, Price: wtAmount, TaxCode: 'IVAEXC' };
  })
  .filter(l => l.Price > 0);

  const withholdingData = retenLines
    .map(t => {
      const wtAmount = parseFloat(t.retentionAmount ?? t.retention ?? 0);
      const mapped   = retenMap[t.code] ?? { wtCode: t.code };
      const baseReten = t.base ? parseFloat(t.base) : 0;
      return { WTCode: mapped.wtCode, WTAmount: wtAmount, TaxableAmount: wtAmount, Rate: 100, U_HBT_BaseRet: baseReten };
    })
    .filter(w => w.WTAmount > 0);

  // Gastos adicionales por impuesto al consumo (TaxCode IVAEXC, no como impuesto de línea)
  const consumoExpenses = consumoLines
    .map(t => ({
        ExpenseCode: CONSUMO_EXP_CODE,
        LineTotal: parseFloat(t.taxAmount ?? t.tax ?? 0),
        TaxCode: 'IVAEXC',
        DistributionMethod: 'aedm_None',
        DistributionRule: 'CO',
        DistributionRule4: oficina,
        DistributionRule5: area,
    }))
    .filter(e => e.LineTotal > 0);

  const doc = {
    CardCode: $('Switch2').item.json.body?.value?.[0]?.CardCode ?? $('Switch2').item.json.body?.CardCode,
    DocDate: docDate,
    DocDueDate: docDate,
    Comments: $json.Note,
    SalesPersonCode: (() => {
      const num = parseInt($('Rindegastos getExpenseReport').first().json?.ExpenseReports?.Employee?.Number, 10);
      return Number.isFinite(num) ? num : -1;
    })(),
    NumAtCard: $json.ExtraFields.find(f => f.Name === "Número de Documento").Value,
    Series: parseInt($json.ExtraFields.find(f => f.Name === "Tipo de Documento").Code),
    DocumentLines: [...taxDocLines, ...retenDocLines],
  };
  if (withholdingData.length > 0) doc.WithholdingTaxDataCollection = withholdingData;
  if (consumoExpenses.length > 0) doc.DocumentAdditionalExpenses = consumoExpenses;
  return doc;
})()) }}

