const items = $input.first().json.items ?? [];
const exitos    = items.filter(i => i.result === 'success' && i.tipo !== 'Proveedor');
const yaExistia = items.filter(i => i.result === 'ya_existia');
const errores   = items.filter(i => i.result === 'error' && i.tipo !== 'Proveedor');
const bpExitos  = items.filter(i => i.result === 'success' && i.tipo === 'Proveedor');
const bpErrores = items.filter(i => i.result === 'error' && i.tipo === 'Proveedor');

// Errores ignorables: asientos con categoría no soportada
// (no son tipos relevantes para integrar en Rindegastos)
const esErrorIgnorable = (e) =>
  e.tipo === 'asiento' && (e.mensaje ?? '').includes('Categoría de asiento no soportada');

const erroresRelevantes = errores.filter(e => !esErrorIgnorable(e));

const allDocNums = [
  ...exitos.map(e => String(e.DocNum)),
  ...yaExistia.filter(e => e.DocNum).map(e => String(e.DocNum))
].filter(Boolean);
const docNums = allDocNums.join(',');

const hayExitos  = (exitos.length + yaExistia.length) > 0;
const hayErrores = errores.length > 0 || bpErrores.length > 0;

// Solo errores relevantes (facturas + asientos Taxis/Peajes) y errores de socios de negocio afectan la integración
const reportIntegrationStatus = (erroresRelevantes.length > 0 || bpErrores.length > 0) ? 0 : 1;

const integrables = [
  ...exitos.filter(e => e.expenseId).map(e => ({ expenseId: e.expenseId, docNum: e.DocNum ?? '', integrationStatus: 1 })),
  ...yaExistia.filter(e => e.expenseId).map(e => ({ expenseId: e.expenseId, docNum: e.DocNum ?? '', integrationStatus: 1 })),
  ...erroresRelevantes.filter(e => e.expenseId).map(e => ({ expenseId: e.expenseId, docNum: '', integrationStatus: 0 }))
];
const hayIntegrables = integrables.length > 0;

let tituloEnvio;
if (!hayErrores) {
  tituloEnvio = 'Envio exitoso';
} else if (!hayExitos) {
  tituloEnvio = 'Envio fallido';
} else {
  tituloEnvio = 'Envio con errores';
}

let resumen = '';
if (exitos.length > 0) {
  const lista = exitos.map(e => {
    if (e.tipo === 'asiento') return `• ${e.supplier}: Asiento SAP #${e.DocNum}`;
    return `• ${e.supplier ? e.supplier + ' NIT ' : ''}${e.CardCode}: Factura SAP #${e.DocNum}`;
  }).join('\n');
  resumen += `${exitos.length} factura(s) creadas exitosamente:\n${lista}`;
}
if (yaExistia.length > 0) {
  if (resumen) resumen += '\n\n';
  const lista = yaExistia.map(e => {
    const docInfo = e.DocNum ? ` (DocNum SAP: #${e.DocNum})` : '';
    const quienEs = e.supplier ? `${e.supplier} NIT ${e.CardCode}` : e.CardCode;
    return `• Factura - ${quienEs}: Ya existia en SAP${docInfo}`;
  }).join('\n');
  resumen += `${yaExistia.length} factura(s) ya existentes en SAP:\n${lista}`;
}
if (errores.length > 0) {
  if (resumen) resumen += '\n\n';
  const lista = errores.map(e => {
    const quienEs = e.supplier ? `${e.supplier} NIT ${e.CardCode}` : (e.CardCode ?? e.nit ?? 'NIT desconocido');
    return `• ${quienEs}: ${e.mensaje}`;
  }).join('\n');
  resumen += `${errores.length} error(es):\n${lista}`;
}

let resumenSocios = '';
if (bpExitos.length > 0) {
  const lista = bpExitos.map(e => `• ${e.Supplier ? e.Supplier + ' - ' : ''}NIT ${e.CardCode ?? e.nit}: Creado en SAP`).join('\n');
  resumenSocios += `${bpExitos.length} socio(s) de negocio creado(s):\n${lista}`;
}
if (bpErrores.length > 0) {
  if (resumenSocios) resumenSocios += '\n\n';
  const lista = bpErrores.map(e => `• ${e.Supplier ? e.Supplier + ' - ' : ''}NIT ${e.nit ?? e.CardCode ?? 'desconocido'}: ${e.mensaje}`).join('\n');
  resumenSocios += `${bpErrores.length} socio(s) de negocio con error:\n${lista}`;
}

return [{ json: { resumen, resumenSocios, docNums, hayExitos, hayErrores, hayIntegrables, integrables, reportIntegrationStatus, tituloEnvio } }];

const items = $input.all();
const switchItems = $('WTCodes Coinciden').all();

function isDuplicateRefError(json) {
  // Solo es "ya existía" si el mensaje contiene el código específico de duplicado SAP (10001467)
  // El -5002 genérico "Internal error" es un error real que debe reportarse
  function hasDuplicateMsg(value) {
    return typeof value === 'string' && value.includes('10001467');
  }

  let body = json.body;
  if (typeof body === 'string' && body) {
    try { body = JSON.parse(body); } catch (_) {}
  }
  if (body?.error?.code === -5002) {
    return hasDuplicateMsg(body.error.message?.value);
  }

  const raw = json.error?.message ?? '';
  try {
    const first = raw.indexOf('"');
    const last = raw.lastIndexOf('"');
    if (first >= 0 && last > first) {
      const unescaped = JSON.parse('"' + raw.slice(first + 1, last) + '"');
      const parsed = JSON.parse(unescaped);
      if (parsed?.error?.code === -5002) {
        return hasDuplicateMsg(parsed.error.message?.value);
      }
    }
  } catch (_) {}
  return false;
}

function parseSapError(json) {
  const status = json.statusCode ?? '';
  const prefix = `Error${status ? ' ' + status : ''} al crear factura en SAP`;

  let body = json.body;
  if (typeof body === 'string' && body) {
    try { body = JSON.parse(body); } catch (_) {}
  }
  if (body?.error?.code !== undefined) {
    const value = body.error.message?.value ?? 'Error desconocido';
    return `${prefix}: ${value}`;
  }

  const raw = json.error?.message ?? '';
  if (!raw) return prefix;

  const effectiveStatus = status || (raw.match(/^(\d+)/) || [])[1] || '';
  const effectivePrefix = `Error${effectiveStatus ? ' ' + effectiveStatus : ''} al crear factura en SAP`;

  try {
    const first = raw.indexOf('"');
    const last = raw.lastIndexOf('"');
    if (first >= 0 && last > first) {
      const unescaped = JSON.parse('"' + raw.slice(first + 1, last) + '"');
      const parsed = JSON.parse(unescaped);
      if (parsed?.error?.code !== undefined) {
        const value = parsed.error.message?.value ?? 'Error desconocido';
        return `${effectivePrefix}: ${value}`;
      }
    }
  } catch (_) {}

  return `${effectivePrefix}: ${raw}`;
}

return items.map((item, i) => {
  const json = item.json;
  const swItem = switchItems[i] ?? switchItems[0];
  const cardCode = swItem?.json?.body?.value?.[0]?.CardCode
    ?? swItem?.json?.body?.CardCode
    ?? 'Desconocido';
  const expenseId = swItem?.json?.Id ?? null;

  if (json.statusCode === 201) {
    return {
      json: {
        result: 'success',
        DocNum: String(json.body?.DocNum ?? ''),
        CardCode: cardCode,
        supplier: swItem?.json?.Supplier ?? cardCode,
        expenseId
      }
    };
  }

  if (isDuplicateRefError(json)) {
    const numAtCard = swItem?.json?.ExtraFields?.find(f => f.Name === 'Número de Documento')?.Value ?? '';
    return {
      json: {
        result: 'ya_existia',
        CardCode: cardCode,
        supplier: swItem?.json?.Supplier ?? cardCode,
        numAtCard,
        expenseId
      }
    };
  }

  return {
    json: {
      result: 'error',
      tipo: 'Factura',
      CardCode: cardCode,
      supplier: swItem?.json?.Supplier ?? null,
      expenseId: swItem?.json?.Id ?? null,
      mensaje: parseSapError(json)
    }
  };
});

const seen = new Set();
const result = [];
for (const item of items) {
  const nit = item.json.nitProveedor;
  if (!seen.has(nit)) {
    seen.add(nit);
    result.push(item);
  }
}
return result;

const items = $input.all();
return items.map(item => {
  const json = item.json;

  // Soporta tanto respuesta GET/filter (body.value[0]) como POST/create (body directamente)
  const vendorWTCodes = new Set(
    (json.body?.value?.[0]?.BPWithholdingTaxCollection
      ?? json.body?.BPWithholdingTaxCollection
      ?? []).map(w => w.WTCode)
  );

  const allTaxes = json.MultipleTaxes?.taxes ?? [];
  const retenLines = allTaxes.filter(t =>
    t.code && (t.type === 2 || parseFloat(t.retentionAmount ?? 0) > 0)
  );

  const plannedWTCodes = retenLines.map(t => t.code);

  // Sin retenciones planeadas → sin problema
  if (plannedWTCodes.length === 0) {
    return { json: { ...json, _wtCodeMismatch: false } };
  }

  const missing = plannedWTCodes.filter(code => !vendorWTCodes.has(code));

  return {
    json: {
      ...json,
      _wtCodeMismatch: missing.length > 0,
      _wtCodesMissing: missing,
      _wtCodesVendor: [...vendorWTCodes],
      _wtCodesPlanned: plannedWTCodes,
    }
  };
});

const result = [];
for (const item of $input.all()) {
  const ef     = item.json.ExtraFields ?? [];
  const nit    = item.json.nitProveedor;
  const nombre = item.json.Supplier;

  const federalTaxID = ef.find(f => f.Name === 'NIT Proveedor')?.Value ?? ef[0]?.Value ?? null;
  const telefono     = ef.find(f => f.Name === 'Telefono')?.Value ?? null;
  const direccion    = ef.find(f => f.Name === 'Dirección proveedor')?.Value ?? null;
  const correo       = ef.find(f => f.Name === 'Correo')?.Value ?? null;
  const municipio    = ef.find(f => f.Name === 'Municipio proveedor')?.Code ?? null;

  const missing = [];
  if (!nit)          missing.push('CardCode (nitProveedor)');
  if (!nombre)       missing.push('CardName (Supplier)');
  if (!federalTaxID) missing.push('FederalTaxID (NIT Proveedor)');
  if (!telefono)     missing.push('Phone1 (Telefono)');
  if (!direccion)    missing.push('Dirección proveedor');
  if (!correo)       missing.push('EmailAddress (Correo)');
  if (!municipio)    missing.push('U_HBT_MunMed (Municipio proveedor)');

  result.push({
    json: {
      ...item.json,
      _bpValid:   missing.length === 0,
      _bpMissing: missing
    }
  });
}
return result;

