const sapItems = $input.all();
const expItems = $('If Tiene encargadoNit').all();

return sapItems.map((sapItem, i) => {
  const sapJson = sapItem.json;
  const exp = expItems[i]?.json ?? {};
  const encargadoNit = exp.encargadoNit;
  const debitorAccount = sapJson.body?.value?.[0]?.DebitorAccount ?? null;

  if (!debitorAccount) {
    return { json: { ...exp, _debitorError: 'No se encontró cuenta deudora (DebitorAccount) en SAP para ' + (encargadoNit ?? 'proveedor desconocido') } };
  }

  const reportId = $('On form submission').first().json['id_informe_de_gastos'];
