  const oficina = exp.ExtraFields?.find(f => f.Name === 'Oficina')?.Code;
  const area    = exp.ExtraFields?.find(f => f.Name === 'Area')?.Code;
  const net     = parseFloat(exp.Net ?? 0);
  const issueDate = (exp.IssueDate).split('T')[0] + 'T00:00:00Z';

  const entry = {
