    ]
  };
  return { json: { ...exp, _journalEntry: entry } };
});

const items = $input.all();
const srcItems = $('Code Preparar JournalEntry').all();

function parseSapAsientoError(json) {
  const status = json.statusCode ?? '';
  const prefix = 'Error' + (status ? ' ' + status : '') + ' al crear asiento en SAP';
  let body = json.body;
  if (typeof body === 'string' && body) {
    try { body = JSON.parse(body); } catch (_) {}
  }
  if (body?.error?.message?.value) {
    return prefix + ': ' + body.error.message.value;
  }
  const raw = json.error?.message ?? '';
  if (raw) return prefix + ': ' + raw;
  return prefix;
}

return items.map((item, i) => {
