  const supplier     = src?.json?.Supplier ?? encargadoNit;

  if (json.statusCode === 201) {
    return { json: {
      result: 'success',
      tipo: 'asiento',
      DocNum: String(json.body?.JdtNum ?? json.body?.DocNum ?? ''),
      CardCode: encargadoNit,
      supplier,
      expenseId
    }};
  }

  return { json: {
    result: 'error',
    tipo: 'asiento',
    CardCode: encargadoNit,
    supplier,
    expenseId,
    mensaje: parseSapAsientoError(json)
  }};
});

